<?php
namespace App\Services;
use PDO;
final class MatcherService {
 public static function match(PDO $db,int $wid,int $txId):?int { $s=$db->prepare('SELECT * FROM bank_transactions WHERE id=? AND workspace_id=?');$s->execute([$txId,$wid]);$t=$s->fetch();if(!$t)return null;$q=$db->prepare("SELECT d.*,COALESCE((SELECT SUM(p.amount) FROM payments p WHERE p.document_id=d.id),0) paid FROM documents d WHERE d.workspace_id=? AND d.doc_type IN ('invoice','proforma') AND d.payment_status!='paid'");$q->execute([$wid]);$best=null;$bestScore=0;foreach($q->fetchAll() as $d){$remaining=max(0,(float)$d['total_with_vat']-(float)$d['paid']);$score=0;if(abs($remaining-(float)$t['amount'])<0.01)$score+=55;elseif(abs($remaining-(float)$t['amount'])<1)$score+=35;$vs=preg_replace('/\D/','',(string)$t['variable_symbol']);$dvs=preg_replace('/\D/','',(string)$d['variable_symbol']);if($vs&&$dvs&&$vs===$dvs)$score+=40;if($t['message']&&stripos((string)$t['message'],(string)$d['doc_number'])!==false)$score+=10;if($score>$bestScore){$bestScore=$score;$best=(int)$d['id'];}}$status=$best&&$bestScore>=90?'matched':($best?'suggested':'unmatched');$db->prepare('UPDATE bank_transactions SET matched_document_id=?,match_score=?,status=?,matched_at=CASE WHEN ?="matched" THEN CURRENT_TIMESTAMP ELSE matched_at END WHERE id=? AND workspace_id=?')->execute([$best,$bestScore,$status,$status,$txId,$wid]);if($status==='matched'&&$best){$exists=$db->prepare('SELECT COUNT(*) FROM payments WHERE bank_transaction_id=?');$exists->execute([$txId]);if(!(int)$exists->fetchColumn()){$db->prepare('INSERT INTO payments(workspace_id,document_id,amount,paid_at,method,source,bank_transaction_id) VALUES(?,?,?,?,?,?,?)')->execute([$wid,$best,(float)$t['amount'],$t['booked_at'],'bank','auto',$txId]);DocumentService::refreshPaymentStatus($db,$wid,$best);}}return $best; }
}
